	@Test
	void aWildcardBufferPricesItsProducedRowsBeforeTheFirstConsumedRow() throws Exception {
		initialize(true);
		assertThat(LmdbNativeKernelExecution.rowFillSize(true)).isGreaterThan(expected().size());
		LmdbNativeDecisionTestAccess.Captured full = selectedQuote(WILDCARD, QUERY);
		LmdbNativeDecisionTestAccess.Captured first = selectedQuote(WILDCARD, QUERY + " LIMIT 1");
		assertThat(full.expectedFeatures()[Feature.OUTPUT_MATERIALIZATION.ordinal()])
				.as("the estimated output population is positive and fits in one physical buffer")
				.isGreaterThan(1D)
				.isLessThan((double) LmdbNativeKernelExecution.rowFillSize(true));
		assertThat(first.expectedFeatures()[Feature.OUTPUT_MATERIALIZATION.ordinal()]).isEqualTo(1D);
		assertThat(full.expectedFeatures()[Feature.INTERPRETED_ROW.ordinal()]).isPositive();
		for (Feature feature : Feature.values()) {
			if (feature != Feature.OUTPUT_MATERIALIZATION) {
				assertThat(first.expectedFeatures()[feature.ordinal()])
						.as("the replay-safe kernel fills the same complete producer buffer before LIMIT 1: %s",
								feature)
						.isEqualTo(full.expectedFeatures()[feature.ordinal()]);
			}
		}
		assertThat(canonical(evaluate(repository, WILDCARD, QUERY + " LIMIT 1")))
				.hasSize(1)
				.allMatch(expected()::contains);
	}

