	private LmdbNativeDecisionTestAccess.Captured selectedQuote(String forcing, String query) throws Exception {
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		try (AutoCloseable capture = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
			evaluate(repository, forcing, query);
		}
		assertThat(selected).singleElement().satisfies(selection -> assertThat(selection.id()).isEqualTo(forcing));
		return selected.getFirst().quote();
	}

	/** Transparent source wrapper; only the requested wildcard binding is fault-injected. */
	private static final class ProbeTracker {
		final NativeLmdbQuerySource delegate;
		final boolean failBinding;
		final IOException bindingFailure = new IOException("injected wildcard binding failure");
		int opened, closed, duplicateCloses, wildcardRequests;

		ProbeTracker(NativeLmdbQuerySource delegate, boolean failBinding) {
			this.delegate = delegate;
			this.failBinding = failBinding;
		}

		NativeLmdbQuerySource source() {
			return (NativeLmdbQuerySource) Proxy.newProxyInstance(NativeLmdbQuerySource.class.getClassLoader(),
					new Class<?>[] { NativeLmdbQuerySource.class }, (proxy, method, args) -> {
						Object result = invoke(delegate, method, args);
						return result instanceof NativeLmdbQuerySource.NativeProbe probe ? probe(probe) : result;
					});
		}

		NativeLmdbQuerySource.NativeProbe probe(NativeLmdbQuerySource.NativeProbe delegate) {
			opened++;
			boolean[] done = { false };
			return (NativeLmdbQuerySource.NativeProbe) Proxy.newProxyInstance(
					NativeLmdbQuerySource.NativeProbe.class.getClassLoader(),
					new Class<?>[] { NativeLmdbQuerySource.NativeProbe.class }, (proxy, method, args) -> {
						if (method.getName().equals("wildcardAdjacency")) {
							wildcardRequests++;
							if (failBinding) {
								throw bindingFailure;
							}
							return null;
						}
						if (method.getName().equals("close")) {
							if (done[0]) {
								duplicateCloses++;
							} else {
								closed++;
							}
							done[0] = true;
						}
						return invoke(delegate, method, args);
					});
		}

		private static Object invoke(Object target, Method method, Object[] args) throws Throwable {
			try {
				return method.invoke(target, args);
			} catch (InvocationTargetException failure) {
				throw failure.getCause();
			}
		}
	}

	private void initialize(boolean adjacencyEnabled) throws Exception {
		store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacencyEnabled)
				.setDirectAdjacencyMode(adjacencyEnabled ? DirectAdjacencyMode.PREFER : DirectAdjacencyMode.DISABLED)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL)
				.setDirectAdjacencyMaxBytes(LmdbStoreConfig.DIRECT_ADJACENCY_MIN_EXPLICIT_BYTES));
		repository = new SailRepository(store);
		memory = new SailRepository(new MemoryStore());
		for (SailRepository target : List.of(repository, memory)) {
			target.init();
			try (var connection = target.getConnection()) {
				var values = connection.getValueFactory();
				connection.begin();
				for (int root = 1; root <= 16; root++) {
					var subject = values.createIRI(NS + root);
					connection.add(subject, values.createIRI(FIRST), values.createIRI(NS + (root + 100)));
					connection.add(subject, values.createIRI(SECOND), values.createIRI(NS + (root + 200)));
				}
				connection.commit();
			}
		}
		if (adjacencyEnabled) {
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		}
		set(NATIVE, "false");
		assertThat(canonical(evaluate(memory, null))).as("independent MemoryStore bag")
				.containsExactlyInAnyOrderElementsOf(expected());
		assertThat(canonical(evaluate(repository, null))).as("generic LMDB bag")
				.containsExactlyInAnyOrderElementsOf(expected());
		set(NATIVE, "true");
	}

	private static List<BindingSet> evaluate(SailRepository target, String forcing) {
		return evaluate(target, forcing, QUERY);
	}

	private static List<BindingSet> evaluate(SailRepository target, String forcing, String sparql) {
		try (var connection = target.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
			query.setForcedLmdbExecutionStrategy(forcing);
			try (var result = query.evaluate()) {
				return QueryResults.asList(result);
			}
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		return rows.stream()
				.map(row -> row.getValue("s").stringValue() + "|"
						+ row.getValue("a").stringValue() + "|" + row.getValue("p").stringValue() + "|"
						+ row.getValue("b").stringValue())
				.toList();
	}

	private static List<String> expected() {
		return IntStream.rangeClosed(1, 16)
				.boxed()
				.flatMap(root -> List.of(
						NS + root + "|" + NS + (root + 100) + "|" + FIRST + "|" + NS + (root + 100),
						NS + root + "|" + NS + (root + 100) + "|" + SECOND + "|" + NS + (root + 200)).stream())
				.toList();
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
